"""Load generated bytecode under the original module names.

Separate _fw_ names prevent uploaded .py sources from taking precedence over
.mpy files. Missing bytecode is an upload error; never silently compile source.
"""
import gc
import sys


def load(name):
    if name in sys.modules:
        return sys.modules[name]
    gc.collect()
    try:
        module = __import__("_fw_" + name)
    except ImportError:
        print("Missing or incompatible _fw_{}.mpy; upload the generated firmware files.".format(name))
        raise
    sys.modules[name] = module
    gc.collect()
    return module
